# Generated by build.py from recipe.yml for recipe webtransport-open-a-stream. Do not edit.
Set-Location $PSScriptRoot
cmd /c 'openssl req -x509 -newkey rsa:2048 -nodes -keyout server.key -out server.pem -days 30 -subj "/CN=127.0.0.1" -addext "subjectAltName=IP:127.0.0.1"'
$server0 = Start-Process surl -ArgumentList '--cert', 'server.pem', '--key', 'server.key', '--allow-anonymous', 'webtransport://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe --cacert server.pem -d "hello over a stream" webtransport://127.0.0.1:8080/echo } finally { Stop-Process $server0 }
